  repository(owner: "FSM1", name: "cipher-box") {
    pullRequest(number: 594) {
      reviewThreads(first: 100) {
        nodes { id isResolved path line comments(first:1){ nodes { author{login} } } }
      }
    }
  }
}' 2>/dev/null | jq -r '.data.repository.pullRequest.reviewThreads.nodes[] | "\(.id)\t\(.isResolved)\t@\(.comments.nodes[0].author.login)\t\(.path):\(.line)"'
echo ""
echo "=== has CodeRabbit posted a review yet? (review bodies) ==="
env -u GITHUB_TOKEN gh api graphql -f query='
{ repository(owner:"FSM1", name:"cipher-box"){ pullRequest(number:594){
  reviews(first:20){ nodes { author{login} state submittedAt bodyText } } } } }' 2>/dev/null | jq -r '.data.repository.pullRequest.reviews.nodes[] | "@\(.author.login) [\(.state)] \(.submittedAt) — \((.bodyText//"")[0:100])"'
